(async()=>{
  const E=window.__echoes;
  const seen=new Set(); const log=[];
  const collect=()=>{ for(const e of E.events){ if(!seen.has(e)){ seen.add(e); log.push(e); } } };
  const sleep=(ms)=>new Promise(r=>setTimeout(r,ms));
  collect();
  E.cmd('startRun');
  const trace=[]; let lastPhase=null,lastRoom=null;
  const t0=Date.now(); let guard=0;
  while(Date.now()-t0<420000){
    collect();
    const v=E.cmd('runState');
    if(v.phase!==lastPhase||v.room!==lastRoom){
      trace.push({room:v.room,phase:v.phase,mode:v.mode,wallet:v.wallet,free:v.freeSkillSlots,tick:E.tick,
        reward:v.reward?{t:v.reward.type,id:v.reward.id,prom:v.reward.promised,sub:v.reward.substituted,line:v.reward.line}:null,
        path:v.path?v.path.options.map(o=>o.win+'/'+o.reward):null,
        shop:v.shop?v.shop.stock.map(s=>s.node+':'+s.price+':'+(s.affordable?'aff':'no')):null});
      lastPhase=v.phase; lastRoom=v.room;
    }
    if(v.phase==='victory'||v.phase==='defeat') break;
    if(v.phase==='combat'){
      if(v.room===8){ E.cmd('killBoss'); }
      else if(v.mode==='kill_all'){ E.cmd('killAllEnemies'); }
      else { E.cmd('killAllEnemies'); }
    } else if(v.phase==='reward'){ E.cmd('draftTake'); }
    else if(v.phase==='path'){ E.cmd('pathChoose', 0); }
    else if(v.phase==='shop'){ E.cmd('shopBuy',0); E.cmd('shopAdvance'); }
    await sleep(120);
    if(++guard>4000) break;
  }
  collect();
  const fin=E.cmd('runState');
  return {trace, final:{phase:fin.phase,room:fin.room,wallet:fin.wallet,summary:fin.summary},
    events:log.filter(e=>/room_enter|room_start|room_cleared|reward_offer|draft_taken|draft_declined|path_offer|path_chosen|glint_gain|shop_|run_start|run_end|victory|defeat|boss_/.test(e.type)).map(e=>e.tick+':'+e.type+':'+JSON.stringify(Object.keys(e).filter(k=>k!=='tick'&&k!=='type').reduce((a,k)=>(a[k]=e[k],a),{})))};
})()
